(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.018-t*0.28)*18 + Math.sin(x*0.016+t*0.32)*12;
  const w2x = Math.sin(x*0.035-t*0.5)*8 + Math.cos(y*0.04+t*0.45)*6;
  const w2y = Math.cos(y*0.032+t*0.48)*8 + Math.sin(x*0.038-t*0.52)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.8],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.2],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.9],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.1],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.7],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.11,2.1,1.3],
    [400+Math.cos(t*0.38+2)*60,200+Math.sin(t*0.72)*55,0.085,1.8,0.85],
    [200+Math.sin(t*0.55+4)*90,220+Math.cos(t*0.42)*65,0.095,2.4,1.05]
  ];
  let aS=0,iS=0,mS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave=Math.sin(d*f-t*sp);
    const tang=Math.sin(d*f*0.6+Math.atan2(sy-sY,sx-sX)*2-t*sp*0.8);
    aS+=wave*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    mS+=tang*w*0.5;
  }
  const n=9,act=aS/n,inh=iS/n,mod=mS/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg2=(Math.sin(sx*0.07-sy*0.05+t*1.8)+Math.cos(sx*0.05+sy*0.08-t*1.4))*0.3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2=(Math.sin(dist*0.08+ang*5+t*0.9)*Math.cos(dist*0.06-ang*2-t*1.1))*0.25;
  const moire=Math.sin(sx*0.2+t*0.7)*Math.sin(sy*0.2-t*0.6)*Math.sin((sx-sy)*0.15+t*0.8)*0.3;
  const rd1=act-inh*0.7+bg*0.3+spiral+spiral2;
  const rd2=Math.tanh(rd1*1.8)-Math.tanh((rd1-0.3)*1.5)*0.4;
  const feedback=Math.sin(rd2*Math.PI*2+t*0.5)*0.15+Math.sin(rd2*Math.PI*3-t*0.7)*0.1;
  const reaction=Math.tanh((rd2+mod*0.4+moire+bg2+feedback)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.22-t*1.2)*Math.cos(sy*0.22+t*0.9)*0.3)*1.5)*0.3;
  const micro=Math.sin(sx*0.4+t*2)*Math.sin(sy*0.4-t*1.8)*Math.sin((sx+sy)*0.3+t*1.5)*0.08;
  const blend=reaction*0.65+cell*0.25+micro,v=blend*0.5+0.5;
  const pal=[[5,12,55],[12,45,95],[18,95,120],[25,150,135],[80,185,140],[170,195,90],[220,175,60],[215,120,65],[175,60,70],[120,35,80],[60,18,60],[5,12,55]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=Math.abs(reaction)>0.65?1.2:Math.abs(reaction)>0.4?1.08:1.0;
  const glow=Math.max(0,reaction)*0.15;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*60)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*80)|0)
  ];
}
